<section class="space-y-4"><h1 class="text-xl font-bold">Audit Log Presensi</h1><form wire:submit="$refresh" class="flex flex-wrap gap-2"><input type="date" wire:model="dateFrom"><input type="date" wire:model="dateTo"><input type="text" wire:model="actionFilter" placeholder="Filter action"><select wire:model="selectedSchoolId"><option value="">Semua sekolah</option>@foreach($schoolOptions as $id=>$name)<option value="{{ $id }}">{{ $name }}</option>@endforeach</select><button type="submit">Filter</button></form><div class="overflow-auto"><table class="w-full text-sm"><thead><tr><th>Waktu</th><th>Actor</th><th>Sekolah</th><th>Action</th><th>Entity</th><th>IP</th><th>User-Agent</th><th>Perubahan</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at?->timezone(config('attendance.timezone'))->format('d-m-Y H:i:s') }}</td><td>{{ $log->actor?->name ?? '-' }}</td><td>{{ $log->school?->name ?? '-' }}</td><td>{{ $log->action }}</td><td>{{ class_basename($log->entity_type) }} #{{ $log->entity_id ?? '-' }}</td><td>{{ $log->ip_address ?? '-' }}</td><td>{{ \Illuminate\Support\Str::limit($log->user_agent,80) }}</td><td><details><summary>Lihat</summary><pre>{{ json_encode(['old'=>$log->old_values,'new'=>$log->new_values], JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE) }}</pre></details></td></tr>@empty<tr><td colspan="8">Belum ada audit log.</td></tr>@endforelse</tbody></table></div></section>
